   const data: SaveData = {
     version: SAVE_VERSION,
     player,
     defeatedBosses: [...defeatedBosses],
     codex,
     appearanceId,
     timestamp: Date.now(),
     timeStep,
     weatherState,
   };
   try {
     localStorage.setItem(SAVE_KEY, JSON.stringify(data));
   } catch (error) {
     debugLog("[save] Failed to save", error);
