1. /**
2.  * Game configuration constants.
3.  */
4. 
5. export const GAME_WIDTH = 640;
6. export const GAME_HEIGHT = 528; // 480 map + 48 HUD message bar
7. export const TILE_SIZE = 32;
8. 
9. /**
10.  * Debug mode — toggled via the [debug mode] checkbox above the game canvas.
11.  * When enabled: shows a debug panel below the game with full action logs
12.  * and live state, prints to the browser console, and enables cheat keys
13.  * in battle (K = kill monster, H = full heal, P = restore MP,
14.  * G = +100 gold, L = level up, X = max XP).
15.  */
16. /** Returns true only for loopback-hosted local development. */
17. export function isLocalDev(): boolean {
18.   const host = globalThis.location?.hostname ?? "localhost";
19.   return host === "localhost"
20.     || host === "127.0.0.1"
21.     || host === "[::1]"
22.     || host.endsWith(".localhost");
23. }
24. 
25. let _debug = false;
26. type DebugListener = (on: boolean) => void;
27. const _listeners: DebugListener[] = [];
28. 
29. export function isDebug(): boolean {
30.   return _debug;
31. }
32. export function toggleDebug(): boolean {
33.   _debug = !_debug;
34.   _listeners.forEach((fn) => fn(_debug));
35.   return _debug;
36. }
37. export function setDebug(on: boolean): void {
38.   if (_debug !== on) {
39.     _debug = on;
40.     _listeners.forEach((fn) => fn(_debug));
41.   }
42. }
43. export function onDebugChanged(fn: DebugListener): void {
44.   _listeners.push(fn);
45. }
46. export function offDebugChanged(fn: DebugListener): void {
47.   const idx = _listeners.indexOf(fn);
48.   if (idx >= 0) _listeners.splice(idx, 1);
49. }
50. export function debugLog(...args: unknown[]): void {
51.   if (_debug) console.log("[DEBUG]", ...args);
52. }
