+import { describe, expect, it, vi } from "vitest";
+import {
+  isWindowFullscreen,
+  setWindowFullscreen,
+} from "../electron/fullscreen";
+
+function createWindowState(native: boolean, simple: boolean) {
+  return {
+    isFullScreen: vi.fn(() => native),
+    isSimpleFullScreen: vi.fn(() => simple),
+    setFullScreen: vi.fn(),
