+function createWindowState(native: boolean, simple: boolean) {
+  return {
+    isFullScreen: vi.fn(() => native),
+    isSimpleFullScreen: vi.fn(() => simple),
+    setFullScreen: vi.fn(),
+    setSimpleFullScreen: vi.fn(),
+  };
+}
